if (Inputs.name !== undefined) {
  (async () => {
    try {
      const name = String(Inputs.name || '');
      if (!name) throw new Error('no file name');
      const cs = globalThis._noodl_cloudservices;
      const res = await fetch(cs.endpoint + '/files/' + encodeURIComponent(name) + '/sign', {
        headers: { 'X-Parse-Master-Key': cs.masterKey }
      });
      if (!res.ok) throw new Error('could not sign ' + name + ' (' + res.status + ')');
      const signed = await res.json();
      const url = new URL(signed.url);
      Outputs.url = url.pathname + url.search;
      Outputs.expiresAt = signed.expiresAt;
      Outputs.done();
    } catch (e) {
      console.error('[dbu:Signed file link]', String((e && e.message) || e));
      Outputs.reason = 'This file could not be opened.';
      Outputs.failed();
    }
  })();
}
